inline bool valid_store_state(const std::array<Id16,4>& ids,std::uint64_t epoch,std::uint16_t flags,std::uint64_t released,std::uint64_t oldest,std::uint64_t newest,std::uint16_t depth,std::uint16_t count) noexcept {const bool rel=flags&1,ret=flags&2,com=flags&4,term=flags&8;for(const auto& id:ids)if(!nonzero(id))return false;if(!epoch||flags&~15||!depth||depth>2||count>depth||ret!=(count>0)||term!=(com&&newest==UINT64_MAX))return false;if(!com)return !rel&&!ret&&!term&&!released&&!oldest&&!newest&&!count;if(ret){if(!com||oldest>UINT64_MAX-(count-1)||newest!=oldest+count-1)return false;if(rel)return released!=UINT64_MAX&&released+1==oldest;return oldest==0;}if(oldest)return false;if(!count&&(!rel||released!=newest))return false;return !rel||released<=newest;}
