inline Result parse_request(std::span<const std::uint8_t>b)noexcept{if(b.size()!=kLength)return{Error::kLength};if(!framing(b,"FGRREL01")||r32(b,12)||r32(b,180)||r32(b,304))return{Error::kFraming};for(auto off:{80U,96U,112U,128U,208U,240U})if(!nonzero(b.subspan(off,off<144?16:32)))return{Error::kInvariant};const auto count=r16(b,176),depth=r16(b,178);const auto first=r64(b,160),last=r64(b,168);if(!count||count>2||!depth||depth>2||count>depth||!r64(b,144)||!r64(b,152)||!r64(b,192)||r64(b,192)<count||!r64(b,200)||last<first)return{Error::kInvariant};const auto range_span=static_cast<std::uint64_t>(count-1);if(range_span>UINT64_MAX-first||last!=first+range_span)return{Error::kInvariant};std::array<std::uint8_t,340> p{};constexpr char tag[]="FORGE-DIRECT-POD-RECORD-RELEASE-EVIDENCE-V1";std::size_t n=0;for(char c:tag){if(c)p[n++]=static_cast<std::uint8_t>(c);}p[n++]=0;for(auto off:{16U,48U,80U,96U,112U,128U})for(std::size_t i=0;i<(off<80?32:16);++i)p[n++]=b[off+i];for(auto off:{144U,152U,160U,168U})for(std::size_t i=0;i<8;++i)p[n++]=b[off+i];for(auto off:{176U,178U})for(std::size_t i=0;i<2;++i)p[n++]=b[off+i];for(auto off:{184U,192U,200U})for(std::size_t i=0;i<8;++i)p[n++]=b[off+i];for(auto off:{208U,240U})for(std::size_t i=0;i<32;++i)p[n++]=b[off+i];return sha256(std::span<const std::uint8_t>{p}.first(n))==protocol::read_array<32>(b,272)?Result{}:Result{Error::kHash};}
